<?php defined('_JEXEC')or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?>
<form action="<?php echo Route::_('index.php?option=com_academy&view=comments'); ?>" method="post" id="adminForm" name="adminForm"><div class="mb-3"><button class="btn btn-success" name="task" value="comments.state">Approve</button> <button class="btn btn-warning" name="task" value="comments.state" onclick="this.form.querySelector('[name=value]').value=0">Unpublish</button> <button class="btn btn-danger" name="task" value="comments.delete">Delete</button></div><table class="table"><thead><tr><th></th><th>Author</th><th>Comment</th><th>Post</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($this->items as $i=>$item):?><tr><td><?php echo HTMLHelper::_('grid.id',$i,$item->id);?></td><td><?php echo htmlspecialchars($item->name,ENT_QUOTES,'UTF-8');?></td><td><?php echo nl2br(htmlspecialchars($item->body,ENT_QUOTES,'UTF-8'));?></td><td><?php echo htmlspecialchars($item->post_title??'',ENT_QUOTES,'UTF-8');?></td><td><?php echo $item->state?'Approved':'Pending';?></td><td><?php echo $item->created;?></td></tr><?php endforeach;?></tbody></table><input type="hidden" name="value" value="1"><?php echo HTMLHelper::_('form.token');?></form>
